#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint   FrameCount;
    // Effect controls
    float  tint_r;         // hologram tint
    float  tint_g;
    float  tint_b;
    float  scan_amp;       // scanline amplitude
    float  scan_freq;      // scanline frequency
    float  jitter;         // horizontal jitter
    float  chroma;         // RGB split in px
    float  grid_amp;       // grid modulation amount
    float  grid_scale;     // grid scale (cells)
    float  vignette;       // edge darken
    float  glow;           // additive glow
};

struct VSIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VSOut { float4 pos [[position]]; float2 uv; };

vertex VSOut main0(VSIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VSOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float rand(float2 x){ return fract(sin(dot(x,float2(12.9898,78.233)))*43758.5453); }

fragment float4 fragment_main(
    VSOut in [[stage_in]],
    texture2d<float> src [[texture(0)]],
    constant Uniforms &u [[buffer(0)]]
){
    constexpr sampler smp(mag_filter::linear, min_filter::linear, address::clamp_to_edge);
    float2 uv = in.uv;
    float2 px = 1.0 / u.OutputSize.xy;
    float t = float(u.FrameCount) / 60.0;

    // Horizontal jitter with subtle per-line noise
    float line = floor(uv.y * u.OutputSize.y);
    float jn = (rand(float2(line, floor(t*17.0))) - 0.5) * 2.0;
    float j = u.jitter * jn * 0.003; // scale to UV
    uv.x = clamp(uv.x + j, 0.0, 1.0);

    // Scanline modulation (intensity waves)
    float scan = 0.5 + 0.5 * sin(uv.y * u.OutputSize.y * u.scan_freq + t*6.28318);
    float scanMix = mix(1.0, scan, clamp(u.scan_amp, 0.0, 1.0));

    // Grid modulation (diagonal interference)
    float2 g = uv * u.grid_scale;
    float grid = 0.5 + 0.5 * (sin(g.x*6.28318) * sin(g.y*6.28318));
    float gridMix = mix(1.0, mix(0.9, 1.1, grid), clamp(u.grid_amp, 0.0, 1.0));

    // Chroma RGB split
    float cpx = u.chroma;
    float r = src.sample(smp, uv + float2( cpx, 0.0) * px).r;
    float gch= src.sample(smp, uv).g;
    float b = src.sample(smp, uv + float2(-cpx, 0.0) * px).b;
    float3 col = float3(r, gch, b);

    // Apply scanline and grid
    col *= scanMix * gridMix;

    // Tint and glow
    float3 tint = float3(u.tint_r, u.tint_g, u.tint_b);
    float3 tinted = col * tint;
    float3 glowCol = tinted + u.glow * pow(tinted, float3(2.0));

    // Vignette
    float2 d = uv - 0.5;
    float vig = smoothstep(0.9, 0.2, dot(d,d)*2.0);
    glowCol *= mix(1.0, vig, clamp(u.vignette, 0.0, 1.0));

    return float4(saturate(glowCol), 1.0);
}

